/* ===== Bảng thuật ngữ (phần 1): tư duy & số liệu, mạng, database, NoSQL & consistency, queue & data ===== */
window.GLOSSARY = [
/* --- 1. Tư duy & số liệu --- */
{ term: 'system design', vi: 'Thiết kế hệ thống', topic: 'design', def: 'Quá trình chọn các thành phần (API, DB, cache, queue...) và cách chúng nối với nhau để đáp ứng yêu cầu chức năng và phi chức năng trong giới hạn chi phí. Không có đáp án duy nhất, chỉ có trade-off được giải thích rõ.', see: ['F1'] },
{ term: 'functional requirement', alt: ['functional requirements', 'yêu cầu chức năng'], vi: 'Yêu cầu chức năng', topic: 'design', def: 'Hệ thống phải LÀM gì: tạo link rút gọn, gửi thông báo, tìm quán gần. Chốt 3–6 dòng trong 5 phút đầu của buổi phỏng vấn.', see: ['F1'] },
{ term: 'non-functional requirement', alt: ['non-functional requirements', 'NFR'], vi: 'Yêu cầu phi chức năng', topic: 'design', def: 'Hệ thống phải làm TỐT đến mức nào: độ trễ, tính sẵn sàng, nhất quán, quy mô, độ bền dữ liệu, chi phí. Đây là thứ quyết định kiến trúc, không phải tính năng.', ex: 'p99 đọc dưới 200 ms, 99,9% uptime, chấp nhận dữ liệu cũ 5 giây.', see: ['F1'] },
{ term: 'trade-off', alt: ['tradeoff', 'trade-offs'], vi: 'Đánh đổi', topic: 'design', def: 'Mọi lựa chọn thiết kế được một thứ thì mất một thứ khác (nhanh hơn nhưng kém nhất quán, rẻ hơn nhưng khó vận hành). Người phỏng vấn chấm việc bạn nêu được cái mất, không chỉ cái được.', see: ['F1', 'K12'] },
{ term: 'back-of-the-envelope', alt: ['back of the envelope', 'back-of-envelope'], vi: 'Ước lượng nhanh', topic: 'design', def: 'Tính nhẩm QPS, dung lượng, băng thông từ vài giả định (DAU, hành vi) với số làm tròn, để quyết định có cần cache, shard, queue hay không.', ex: '100M DAU × 10 đọc / 10^5 giây ≈ 10 000 đọc/giây.', see: ['F2'] },
{ term: 'DAU', alt: ['daily active users'], vi: 'Người dùng hoạt động mỗi ngày', topic: 'design', def: 'Số người dùng dùng hệ thống trong một ngày; điểm xuất phát của mọi phép ước lượng. Nhân với số hành động mỗi người để ra lưu lượng.', see: ['F2'] },
{ term: 'QPS', alt: ['RPS', 'queries per second', 'requests per second'], vi: 'Số truy vấn mỗi giây', topic: 'design', def: 'Lưu lượng trung bình; luôn kèm đỉnh (peak) gấp 2–3 lần. Một máy chủ web xử lý vài nghìn QPS cho request nhẹ, một Postgres ghi vài nghìn giao dịch đơn giản mỗi giây.', see: ['F2'] },
{ term: 'throughput', vi: 'Thông lượng', topic: 'scale', def: 'Lượng việc hệ thống hoàn thành trong một đơn vị thời gian (request/giây, MB/giây, message/giây). Khác với độ trễ: có thể thông lượng cao mà từng request vẫn chậm.', see: ['F1'] },
{ term: 'latency', vi: 'Độ trễ', topic: 'scale', def: 'Thời gian từ lúc gửi request tới lúc nhận phản hồi. Luôn báo theo percentile (p50, p99) chứ không theo trung bình, vì trung bình che mất đuôi chậm.', see: ['F1', 'B14'] },
{ term: 'p99', alt: ['p95', 'p50', 'percentile'], vi: 'Phân vị 99', topic: 'observability', def: 'Giá trị mà 99% request nhanh hơn nó. p99 = 800 ms nghĩa là cứ 100 request có 1 request chậm hơn 0,8 giây. Dùng để đặt SLO vì phản ánh trải nghiệm xấu nhất mà người dùng còn gặp thường xuyên.', see: ['F1', 'B14'] },
{ term: 'tail latency', vi: 'Độ trễ đuôi', topic: 'observability', def: 'Phần request chậm nhất (p99, p99.9). Khi một trang gọi 20 service, xác suất dính ít nhất một request chậm rất cao, nên đuôi của từng service quyết định trải nghiệm tổng.', see: ['B17'] },
{ term: 'availability', vi: 'Tính sẵn sàng', topic: 'scale', def: 'Tỉ lệ thời gian hệ thống phục vụ được request. Đo bằng số "nines": 99,9% cho phép ngừng khoảng 8,7 giờ mỗi năm; 99,99% chỉ 52 phút.', see: ['F9'] },
{ term: 'nines', alt: ['99.9%', 'three nines', 'four nines'], vi: 'Số chín', topic: 'scale', def: 'Cách gọi tắt mức sẵn sàng: 99% (2 nines) ≈ 3,65 ngày downtime/năm; 99,9% ≈ 8,7 giờ; 99,99% ≈ 52 phút; 99,999% ≈ 5 phút. Mỗi chín thêm vào đắt gấp nhiều lần.', see: ['F1', 'F9'] },
{ term: 'SLA', alt: ['service level agreement'], vi: 'Cam kết mức dịch vụ', topic: 'scale', def: 'Hợp đồng với khách hàng về mức dịch vụ (ví dụ 99,9% uptime) kèm hậu quả khi vi phạm (hoàn tiền). SLA đặt lỏng hơn SLO nội bộ để có khoảng đệm.', see: ['F9'] },
{ term: 'SLO', alt: ['service level objective'], vi: 'Mục tiêu mức dịch vụ', topic: 'observability', def: 'Mục tiêu nội bộ đo được cho một SLI, ví dụ "99,5% request thành công trong 30 ngày". SLO quyết định khi nào alert và khi nào dừng ra tính năng để sửa độ ổn định.', see: ['F9', 'B14'] },
{ term: 'SLI', alt: ['service level indicator'], vi: 'Chỉ số mức dịch vụ', topic: 'observability', def: 'Phép đo cụ thể dùng cho SLO: tỉ lệ request thành công, tỉ lệ request dưới 300 ms, độ tươi của dữ liệu. Chọn SLI phản ánh điều người dùng cảm nhận.', see: ['B14'] },
{ term: 'error budget', vi: 'Ngân sách lỗi', topic: 'observability', def: 'Phần lỗi được phép trong kỳ theo SLO (99,9% → 0,1% request được lỗi). Còn ngân sách thì được deploy mạnh tay; cạn ngân sách thì ưu tiên độ ổn định.', see: ['B14'] },
{ term: 'durability', vi: 'Độ bền dữ liệu', topic: 'storage', def: 'Xác suất dữ liệu đã ghi không bị mất. Đạt bằng ghi ra đĩa (fsync), nhân bản sang nhiều máy hoặc vùng. S3 quảng cáo 11 số 9.', see: ['B12'] },
{ term: 'scalability', vi: 'Khả năng mở rộng', topic: 'scale', def: 'Khả năng tăng năng lực xử lý khi thêm tài nguyên. Hệ scale tốt khi thêm máy gần như tăng tuyến tính; điểm nghẽn (DB, API ngoài) làm đường cong gãy.', see: ['F10'] },
{ term: 'vertical scaling', alt: ['scale up'], vi: 'Mở rộng dọc', topic: 'scale', def: 'Thêm CPU, RAM, đĩa cho một máy. Đơn giản, không đổi kiến trúc, nhưng có trần và một máy chết là chết hết.', see: ['F10'] },
{ term: 'horizontal scaling', alt: ['scale out'], vi: 'Mở rộng ngang', topic: 'scale', def: 'Thêm nhiều máy chạy song song sau load balancer. Đòi hỏi service stateless hoặc dữ liệu được phân vùng; đổi lại không có trần và chịu lỗi tốt hơn.', see: ['F10'] },
{ term: 'stateless', vi: 'Không trạng thái', topic: 'scale', def: 'Service không giữ dữ liệu phiên trong bộ nhớ giữa các request; mọi trạng thái nằm ở DB, cache hoặc token. Nhờ vậy request nào vào máy nào cũng được, dễ scale và thay máy.', see: ['F10'] },
{ term: 'stateful', vi: 'Có trạng thái', topic: 'scale', def: 'Thành phần giữ dữ liệu giữa các request (DB, kết nối WebSocket, phiên trong RAM). Khó scale và failover hơn; cần sticky session hoặc registry để biết dữ liệu nằm ở đâu.', see: ['B20'] },
{ term: 'single point of failure', alt: ['SPOF'], vi: 'Điểm chết đơn', topic: 'scale', def: 'Thành phần duy nhất mà khi hỏng, cả hệ thống ngừng: một DB không replica, một broker, một gateway. Tìm SPOF là câu hỏi đầu tiên khi bàn độ tin cậy.', see: ['F9'] },
{ term: 'redundancy', vi: 'Dự phòng', topic: 'scale', def: 'Có nhiều hơn một bản của thành phần (nhiều instance, replica, nhiều vùng) để một cái hỏng vẫn còn cái khác. Trả giá bằng chi phí và độ phức tạp đồng bộ.', see: ['F9'] },
{ term: 'failover', vi: 'Chuyển dự phòng', topic: 'consistency', def: 'Tự động chuyển sang bản dự phòng khi bản chính hỏng (promote replica thành primary). Rủi ro: mất dữ liệu chưa replicate và split brain nếu bản cũ sống lại.', see: ['B2'] },
{ term: 'active-active', alt: ['active-passive', 'active/active'], vi: 'Chủ động kép / chủ động-dự phòng', topic: 'scale', def: 'Active-active: nhiều bản cùng phục vụ, tận dụng tài nguyên nhưng phải giải quyết xung đột ghi. Active-passive: một bản phục vụ, bản kia chờ, failover đơn giản hơn nhưng lãng phí.', see: ['F9'] },
{ term: 'bottleneck', vi: 'Điểm nghẽn', topic: 'scale', def: 'Thành phần chậm nhất quyết định thông lượng cả hệ thống. Thường là DB hoặc API bên ngoài; tìm bằng số liệu (CPU, queue depth, p99) chứ không đoán.', see: ['F10', 'L11'] },
{ term: 'hot key', alt: ['hot partition', 'hot shard', 'hotspot'], vi: 'Khoá nóng', topic: 'scale', def: 'Một key hoặc một phân vùng nhận lượng truy cập vượt trội so với phần còn lại (bài viết viral, tenant lớn), làm một node quá tải trong khi các node khác rảnh. Xử lý bằng cache cục bộ, salting, tách key.', see: ['B3', 'F7'] },
{ term: 'celebrity problem', vi: 'Bài toán người nổi tiếng', topic: 'scale', def: 'Người dùng có hàng triệu follower khiến fan-out on write tốn hàng triệu thao tác cho một bài đăng. Giải bằng mô hình lai: người thường fan-out khi ghi, người nổi tiếng gộp khi đọc.', see: ['C6'] },
{ term: 'fan-out', alt: ['fanout', 'fan-out on write', 'fan-out on read'], vi: 'Toả ra', topic: 'scale', def: 'Một sự kiện sinh ra nhiều thao tác tới nhiều đích. Fan-out on write: đẩy sẵn vào feed của từng follower lúc đăng (đọc nhanh, ghi tốn). Fan-out on read: gộp lúc người dùng mở feed (ghi rẻ, đọc chậm).', see: ['C6', 'C5'] },
{ term: 'idempotency', alt: ['idempotent'], vi: 'Tính luỹ đẳng', topic: 'api', def: 'Thực hiện cùng một yêu cầu nhiều lần cho kết quả như một lần. Điều kiện bắt buộc để retry an toàn và để chấp nhận at-least-once delivery.', ex: 'Trừ tiền hai lần vì retry là lỗi thiếu idempotency.', see: ['F6', 'F8', 'C11'] },
{ term: 'idempotency key', vi: 'Khoá luỹ đẳng', topic: 'api', def: 'Mã duy nhất client gửi kèm request ghi; server lưu key → kết quả và trả lại kết quả cũ nếu gặp lại key. Cách chuẩn để POST thanh toán, tạo đơn hàng chịu được retry.', see: ['F6', 'C11'] },
{ term: 'at-least-once', alt: ['at least once'], vi: 'Ít nhất một lần', topic: 'queue', def: 'Message chắc chắn được giao nhưng có thể lặp. Là mặc định thực tế của mọi hệ queue; đi kèm consumer idempotent để lặp không gây hại.', see: ['F8'] },
{ term: 'at-most-once', alt: ['at most once'], vi: 'Nhiều nhất một lần', topic: 'queue', def: 'Message không bao giờ lặp nhưng có thể mất (gửi rồi quên). Chấp nhận được với metric, log không quan trọng; không dùng cho lệnh nghiệp vụ.', see: ['F8'] },
{ term: 'exactly-once', alt: ['exactly once', 'effectively-once'], vi: 'Đúng một lần', topic: 'queue', def: 'Mục tiêu lý tưởng không đạt được ở tầng mạng; trong thực tế là at-least-once + xử lý idempotent (dedup), nên gọi đúng hơn là effectively-once. Kafka transactions chỉ bảo đảm trong phạm vi Kafka.', see: ['F8', 'B7'] },
{ term: 'backpressure', vi: 'Áp lực ngược', topic: 'queue', def: 'Cơ chế bên nhận báo cho bên gửi chậm lại khi quá tải (bounded channel, prefetch, 429) thay vì nhận vô hạn rồi sập vì hết RAM.', see: ['F8', 'B17'] },
{ term: 'thundering herd', vi: 'Đàn thú giẫm đạp', topic: 'scale', def: 'Rất nhiều client cùng hành động một lúc (cùng retry khi mạng hồi, cùng đổ về sau khi cache mất) làm quá tải tức thời. Giảm bằng jitter, giới hạn concurrency, warm-up.', see: ['F9', 'B17'] },
{ term: 'cache stampede', alt: ['dog-pile'], vi: 'Giẫm đạp cache', topic: 'cache', def: 'Khi một key nóng hết hạn, hàng nghìn request cùng miss và cùng truy vấn DB. Chống bằng lock/singleflight (chỉ một request đi tính), TTL có jitter, hoặc làm mới sớm trước khi hết hạn.', see: ['F7', 'L3'] },
{ term: 'retry storm', vi: 'Bão retry', topic: 'scale', def: 'Khi service chậm, client retry làm tải tăng gấp bội, khiến nó chậm hơn nữa. Phòng bằng retry budget, exponential backoff + jitter, circuit breaker.', see: ['F9', 'B17'] },
{ term: 'cascading failure', vi: 'Sập dây chuyền', topic: 'scale', def: 'Một thành phần hỏng kéo theo các thành phần khác (DB chậm → pool cạn → API treo → gateway đầy). Chặn bằng timeout, bulkhead, circuit breaker, load shedding.', see: ['F9', 'B17'] },
{ term: 'graceful degradation', vi: 'Suy giảm có kiểm soát', topic: 'scale', def: 'Khi một phụ thuộc hỏng, vẫn phục vụ phần còn lại ở mức kém hơn (hiện feed cũ, tắt gợi ý) thay vì lỗi toàn trang.', see: ['F9'] },
{ term: 'load shedding', vi: 'Xả tải', topic: 'scale', def: 'Chủ động từ chối một phần request (ưu tiên request rẻ hoặc khách quan trọng) khi quá tải để phần còn lại vẫn đúng hạn. Tốt hơn là nhận tất cả rồi tất cả cùng timeout.', see: ['B17'] },
{ term: 'circuit breaker', vi: 'Cầu dao', topic: 'scale', def: 'Bộ đếm lỗi gọi tới một phụ thuộc: quá ngưỡng thì "mở" (từ chối ngay, không gọi nữa) một thời gian, rồi "nửa mở" thử vài request trước khi đóng lại. Tránh dồn tải lên service đang ốm.', see: ['F9', 'B17'] },
{ term: 'bulkhead', vi: 'Vách ngăn', topic: 'scale', def: 'Tách pool tài nguyên (kết nối, goroutine, worker) riêng cho từng phụ thuộc hoặc từng tenant để một phụ thuộc chậm không ăn hết tài nguyên của cả service.', see: ['B17'] },
{ term: 'timeout', alt: ['timeouts'], vi: 'Hết giờ chờ', topic: 'scale', def: 'Giới hạn thời gian chờ một call. Không có timeout, một phụ thuộc treo sẽ giữ kết nối và goroutine mãi mãi. Đặt lồng nhau: client ngắn hơn gateway, gateway ngắn hơn DB.', see: ['F9', 'B17', 'L2'] },
{ term: 'exponential backoff', alt: ['backoff'], vi: 'Lùi theo cấp số nhân', topic: 'scale', def: 'Khoảng chờ giữa các lần retry tăng dần (100 ms, 200, 400, 800...) để service đang quá tải có thời gian hồi. Luôn kèm jitter và giới hạn số lần.', see: ['F9'] },
{ term: 'jitter', vi: 'Nhiễu ngẫu nhiên', topic: 'scale', def: 'Cộng thêm thời gian ngẫu nhiên vào backoff hoặc TTL để các client không đồng loạt retry hoặc đồng loạt hết hạn cache cùng một giây.', see: ['F9', 'F7'] },
{ term: 'deadline propagation', alt: ['deadline'], vi: 'Truyền hạn chót', topic: 'concurrency', def: 'Hạn chót của request gốc được truyền qua mọi call con (Go context) để call con tự huỷ khi request cha đã quá hạn, không làm việc vô ích.', see: ['B17', 'K1'] },
{ term: 'health check', vi: 'Kiểm tra sức khoẻ', topic: 'scale', def: 'Endpoint để load balancer hoặc orchestrator biết instance có nhận được traffic không. Kiểm tra sâu (DB, broker) thì chính xác hơn nhưng dễ làm cả cụm bị rút khỏi LB khi DB chập chờn.', see: ['F9', 'B18'] },
{ term: 'liveness probe', alt: ['readiness probe', 'liveness', 'readiness'], vi: 'Kiểm tra sống / sẵn sàng', topic: 'cloud', def: 'Liveness: tiến trình còn sống không, hỏng thì restart. Readiness: đã sẵn sàng nhận traffic chưa (đã nối DB, warm cache), chưa thì rút khỏi LB nhưng không restart.', see: ['B18'] },
{ term: 'graceful shutdown', vi: 'Tắt êm', topic: 'cloud', def: 'Khi nhận SIGTERM: ngừng nhận request mới, chờ request đang dở xong, đóng consumer/publisher đúng thứ tự, rồi mới thoát. Thiếu nó, mỗi lần deploy là mất message và lỗi 502.', see: ['B17', 'B18', 'K1'] },
{ term: 'rate limiting', alt: ['rate limit', 'rate limiter'], vi: 'Giới hạn tốc độ', topic: 'api', def: 'Giới hạn số request trong một khoảng thời gian theo user, tenant, IP hoặc API key; vượt thì trả 429. Bảo vệ hệ thống khỏi lạm dụng và bảo đảm công bằng giữa khách.', see: ['B9', 'C2', 'L7'] },
{ term: 'token bucket', vi: 'Xô thẻ', topic: 'api', def: 'Thuật toán rate limit: xô chứa tối đa N thẻ, nạp đều r thẻ/giây; mỗi request lấy một thẻ, hết thẻ thì từ chối. Cho phép burst tới N nhưng trung bình không quá r.', see: ['B9', 'L7'] },
{ term: 'leaky bucket', vi: 'Xô rò', topic: 'api', def: 'Request vào hàng đợi và được xử lý với tốc độ cố định như nước rò khỏi xô; đầy xô thì bỏ. Làm mượt lưu lượng nhưng thêm độ trễ xếp hàng.', see: ['B9'] },
{ term: 'sliding window', alt: ['sliding window log', 'sliding window counter', 'fixed window'], vi: 'Cửa sổ trượt', topic: 'api', def: 'Đếm request trong cửa sổ thời gian trượt theo thời điểm hiện tại, tránh lỗi "gấp đôi ở biên" của fixed window (cửa sổ cố định theo phút). Bản log chính xác nhưng tốn bộ nhớ; bản counter xấp xỉ, rẻ.', see: ['B9'] },
{ term: 'throttling', vi: 'Bóp lưu lượng', topic: 'api', def: 'Làm chậm hoặc từ chối request vượt mức thay vì xử lý ngay; rate limit là một dạng throttling. Khi gọi API ngoài, throttle phía client để không bị họ chặn.', see: ['B9'] },
{ term: 'quota', vi: 'Hạn mức', topic: 'api', def: 'Giới hạn tổng theo kỳ dài (1 000 lần scan/tháng, 10 GB lưu trữ) thường gắn với gói dịch vụ, khác với rate limit theo giây.', see: ['B19'] },

/* --- 2. Mạng --- */
{ term: 'DNS', alt: ['domain name system'], vi: 'Hệ thống tên miền', topic: 'net', def: 'Dịch tên miền sang địa chỉ IP, có cache theo TTL ở nhiều tầng. Dùng được để cân bằng tải thô và chuyển vùng, nhưng đổi IP mất thời gian TTL mới có hiệu lực.', see: ['F3'] },
{ term: 'TTL', alt: ['time to live', 'time-to-live'], vi: 'Thời gian sống', topic: 'cache', def: 'Khoảng thời gian một bản ghi (cache, DNS, token) còn hiệu lực trước khi tự hết hạn. TTL ngắn thì tươi nhưng tốn tải; dài thì rẻ nhưng cũ.', see: ['F7', 'F3'] },
{ term: 'TCP', vi: 'Giao thức TCP', topic: 'net', def: 'Giao thức truyền tin cậy, có thứ tự, có kiểm soát tắc nghẽn; thiết lập bằng bắt tay 3 bước (1 RTT). Nền của HTTP/1.1, HTTP/2, gRPC.', see: ['F3', 'K5'] },
{ term: 'UDP', vi: 'Giao thức UDP', topic: 'net', def: 'Giao thức không kết nối, không bảo đảm thứ tự hay giao nhận, nhưng không có độ trễ bắt tay. Dùng cho DNS, video realtime, QUIC.', see: ['F3'] },
{ term: 'TLS', alt: ['SSL', 'HTTPS'], vi: 'Mã hoá đường truyền', topic: 'security', def: 'Lớp mã hoá và xác thực máy chủ trên TCP. TLS 1.3 bắt tay 1 RTT (0-RTT khi nối lại). Thường kết thúc ở load balancer để quản lý chứng chỉ một chỗ.', see: ['F3', 'B15'] },
{ term: 'handshake', alt: ['bắt tay'], vi: 'Bắt tay', topic: 'net', def: 'Các gói trao đổi để thiết lập kết nối (TCP 3 bước, TLS thêm 1–2 RTT). Mỗi kết nối mới trả giá vài RTT, nên keep-alive và connection pool rất quan trọng.', see: ['F3'] },
{ term: 'RTT', alt: ['round trip', 'round-trip time'], vi: 'Thời gian khứ hồi', topic: 'net', def: 'Thời gian gói tin đi và về. Trong một datacenter khoảng 0,5 ms; liên lục địa khoảng 150 ms. Số lần khứ hồi, không phải băng thông, quyết định độ trễ của phần lớn request nhỏ.', see: ['F1', 'F3'] },
{ term: 'HTTP/2', alt: ['HTTP/1.1', 'HTTP/3', 'HTTP2', 'HTTP3'], vi: 'HTTP phiên bản 2 và 3', topic: 'net', def: 'HTTP/1.1: một request một lượt trên mỗi kết nối. HTTP/2: nhiều stream song song trên một kết nối TCP (multiplexing) nhưng mất gói ở TCP làm nghẽn tất cả. HTTP/3: chạy trên QUIC/UDP, mỗi stream độc lập.', see: ['F3', 'K5'] },
{ term: 'QUIC', vi: 'Giao thức QUIC', topic: 'net', def: 'Giao thức trên UDP tích hợp mã hoá và multiplexing, bắt tay 0–1 RTT, không có head-of-line blocking giữa các stream. Nền của HTTP/3.', see: ['F3'] },
{ term: 'keep-alive', alt: ['keepalive', 'persistent connection'], vi: 'Giữ kết nối', topic: 'net', def: 'Dùng lại một kết nối TCP/TLS cho nhiều request thay vì bắt tay lại mỗi lần. Tiết kiệm hàng chục ms mỗi request và tránh cạn ephemeral port.', see: ['F3', 'K5'] },
{ term: 'connection pool', alt: ['connection pooling', 'pool'], vi: 'Bể kết nối', topic: 'db', def: 'Tập kết nối mở sẵn được dùng lại cho nhiều request. Pool quá nhỏ thì request chờ; quá lớn thì DB bị quá tải vì mỗi kết nối Postgres là một tiến trình. Thường bắt đầu từ vài chục cho mỗi instance.', see: ['F5', 'L2'] },
{ term: 'head-of-line blocking', alt: ['HOL blocking', 'head of line blocking'], vi: 'Nghẽn đầu hàng', topic: 'net', def: 'Một gói hoặc request chậm ở đầu hàng chặn mọi thứ phía sau dù chúng đã sẵn sàng. Xảy ra ở HTTP/1.1 (pipelining), ở TCP khi mất gói, và ở queue xử lý tuần tự.', see: ['F3'] },
{ term: 'WebSocket', alt: ['websockets'], vi: 'Kết nối hai chiều', topic: 'realtime', def: 'Kết nối dài hai chiều trên TCP, nâng cấp từ HTTP. Phù hợp chat, realtime; nhưng gateway trở nên stateful nên cần registry kết nối, heartbeat và reconnect.', see: ['F3', 'B20', 'C7'] },
{ term: 'SSE', alt: ['server-sent events'], vi: 'Sự kiện từ server', topic: 'realtime', def: 'Server đẩy luồng sự kiện một chiều qua một kết nối HTTP mở lâu; trình duyệt tự kết nối lại. Đơn giản hơn WebSocket khi chỉ cần server → client (thông báo, tiến độ).', see: ['F3', 'B20'] },
{ term: 'long polling', alt: ['polling'], vi: 'Thăm dò giữ chờ', topic: 'realtime', def: 'Polling: client hỏi định kỳ, lãng phí khi không có gì mới. Long polling: server giữ request tới khi có dữ liệu hoặc hết giờ rồi client hỏi lại; gần realtime mà không cần WebSocket.', see: ['F3', 'C10'] },
{ term: 'CDN', alt: ['content delivery network'], vi: 'Mạng phân phối nội dung', topic: 'net', def: 'Mạng máy chủ biên gần người dùng cache nội dung tĩnh (ảnh, video, JS). Giảm độ trễ và tải gốc; cần nghĩ về cache key, TTL và cách purge khi nội dung đổi.', see: ['B1', 'C9'] },
{ term: 'edge server', alt: ['edge computing', 'edge location'], vi: 'Biên mạng', topic: 'net', def: 'Các điểm hiện diện gần người dùng (POP) của CDN hoặc nền tảng serverless. Chạy logic nhẹ ở biên (redirect, auth, A/B) tiết kiệm một vòng khứ hồi về gốc.', see: ['B1'] },
{ term: 'reverse proxy', vi: 'Proxy ngược', topic: 'net', def: 'Máy chủ đứng trước backend, nhận request từ client rồi chuyển vào (Nginx, Envoy). Làm TLS termination, cache, nén, routing; backend không lộ ra ngoài.', see: ['B1'] },
{ term: 'load balancer', alt: ['LB', 'cân bằng tải'], vi: 'Bộ cân bằng tải', topic: 'scale', def: 'Phân phối request tới nhiều instance theo thuật toán (round robin, least connections, hash), kiểm tra sức khoẻ và rút instance hỏng. Điều kiện để scale ngang.', see: ['F10', 'B1'] },
{ term: 'L4 vs L7', alt: ['L4', 'L7', 'layer 4', 'layer 7'], vi: 'Tầng 4 và tầng 7', topic: 'net', def: 'LB tầng 4 chuyển gói theo IP/port, nhanh, không hiểu HTTP. LB tầng 7 đọc được HTTP nên route theo path, header, cookie, làm TLS termination, nhưng tốn CPU hơn.', see: ['B1'] },
{ term: 'round robin', alt: ['least connections', 'weighted round robin'], vi: 'Xoay vòng / ít kết nối nhất', topic: 'scale', def: 'Round robin chia đều lần lượt, đơn giản nhưng mù với máy đang chậm. Least connections chọn máy ít kết nối đang mở nhất, hợp khi request có độ dài khác nhau.', see: ['F10', 'B1'] },
{ term: 'sticky session', alt: ['session affinity'], vi: 'Phiên dính', topic: 'scale', def: 'LB luôn gửi một client về cùng một instance (theo cookie hoặc IP). Cần khi trạng thái nằm trong RAM của instance; nhưng cản scale và failover, nên ưu tiên stateless.', see: ['F10', 'B20'] },
{ term: 'API gateway', alt: ['gateway'], vi: 'Cổng API', topic: 'api', def: 'Điểm vào duy nhất cho client: xác thực, rate limit, routing tới service, gộp kết quả, ghi log. Tập trung các việc "cắt ngang" để service phía sau tập trung vào nghiệp vụ.', see: ['B1', 'B16'] },
{ term: 'service mesh', alt: ['sidecar'], vi: 'Lưới dịch vụ', topic: 'design', def: 'Hạ tầng đặt một proxy (sidecar) cạnh mỗi service để lo mTLS, retry, timeout, tracing giữa các service. Mạnh nhưng phức tạp vận hành; team nhỏ hiếm khi cần.', see: ['B1', 'B16'] },
{ term: 'mTLS', alt: ['mutual TLS'], vi: 'TLS hai chiều', topic: 'security', def: 'Cả client lẫn server đều xuất trình chứng chỉ, nên service chỉ nhận kết nối từ service được tin. Dùng cho giao tiếp nội bộ giữa microservice.', see: ['B15'] },
{ term: 'NAT', alt: ['network address translation'], vi: 'Chuyển đổi địa chỉ mạng', topic: 'net', def: 'Thiết bị đổi IP riêng sang IP công cộng khi gói ra ngoài. Làm cho máy bên trong không gọi được chính mình qua IP công cộng nếu router không hỗ trợ hairpin.', see: ['B1', 'K5'] },
{ term: 'hairpin NAT', alt: ['NAT loopback'], vi: 'NAT quay đầu', topic: 'net', def: 'Trường hợp máy trong mạng nội bộ gọi dịch vụ cùng mạng bằng hostname/IP công cộng; nhiều router và Docker không trả lời, gây ECONNREFUSED. Bài học: gọi nội bộ bằng tên nội bộ.', see: ['B1', 'K5'] },
{ term: 'anycast', alt: ['GSLB'], vi: 'Anycast / cân bằng tải toàn cầu', topic: 'net', def: 'Một IP được quảng bá từ nhiều nơi, mạng tự đưa người dùng tới điểm gần nhất (CDN, DNS công cộng). GSLB làm việc tương tự ở tầng DNS theo vị trí và sức khoẻ vùng.', see: ['B1'] },

/* --- 3. Database --- */
{ term: 'ACID', vi: 'Bốn tính chất giao dịch', topic: 'db', def: 'Atomicity (tất cả hoặc không gì), Consistency (ràng buộc luôn đúng), Isolation (giao dịch không thấy dở dang của nhau), Durability (đã commit thì không mất). Nền tảng của DB quan hệ.', see: ['F5'] },
{ term: 'transaction', alt: ['giao dịch'], vi: 'Giao dịch', topic: 'db', def: 'Nhóm thao tác được thực hiện trọn vẹn hoặc huỷ toàn bộ. Giữ giao dịch ngắn: giao dịch dài giữ lock, cản VACUUM và dễ deadlock.', see: ['F5', 'K3'] },
{ term: 'isolation level', alt: ['isolation levels', 'mức cô lập'], vi: 'Mức cô lập', topic: 'db', def: 'Mức độ các giao dịch song song thấy dữ liệu dở dang của nhau: read uncommitted, read committed (mặc định Postgres), repeatable read, serializable. Mức càng cao càng an toàn nhưng càng nhiều xung đột/retry.', see: ['F5', 'K3'] },
{ term: 'read committed', alt: ['repeatable read', 'serializable', 'snapshot isolation'], vi: 'Các mức cô lập', topic: 'db', def: 'Read committed: chỉ thấy dữ liệu đã commit, nhưng hai lần đọc trong một giao dịch có thể khác nhau. Repeatable read/snapshot: thấy ảnh chụp cố định. Serializable: như chạy tuần tự, có thể bị huỷ vì xung đột.', see: ['F5', 'K3'] },
{ term: 'dirty read', alt: ['non-repeatable read'], vi: 'Đọc bẩn', topic: 'db', def: 'Đọc được dữ liệu chưa commit của giao dịch khác (Postgres không cho phép). Non-repeatable read: cùng dòng đọc hai lần ra hai giá trị vì giao dịch khác đã commit ở giữa.', see: ['F5'] },
{ term: 'phantom read', vi: 'Đọc ma', topic: 'db', def: 'Chạy lại cùng truy vấn trong một giao dịch thấy thêm hoặc bớt dòng do giao dịch khác chèn/xoá. Chỉ serializable (hoặc khoá phạm vi) chặn hoàn toàn.', see: ['F5'] },
{ term: 'write skew', vi: 'Lệch ghi', topic: 'db', def: 'Hai giao dịch đọc cùng tập dữ liệu rồi mỗi bên ghi vào dòng khác nhau dựa trên điều vừa đọc, kết quả vi phạm ràng buộc dù từng giao dịch đúng (hai bác sĩ cùng xin nghỉ). Cần serializable hoặc khoá tường minh.', see: ['F5', 'C16'] },
{ term: 'MVCC', alt: ['multi-version concurrency control'], vi: 'Kiểm soát đồng thời đa phiên bản', topic: 'db', def: 'DB giữ nhiều phiên bản của một dòng để người đọc không chặn người ghi và ngược lại. Giá phải trả ở Postgres: dòng chết cần VACUUM dọn, bảng phình (bloat).', see: ['F5', 'K3'] },
{ term: 'VACUUM', alt: ['autovacuum'], vi: 'Dọn dòng chết', topic: 'db', def: 'Tiến trình Postgres thu hồi không gian của các phiên bản dòng đã lỗi thời do MVCC và cập nhật thống kê. Autovacuum chạy nền; bảng update nhiều mà vacuum không kịp sẽ phình và chậm.', see: ['F5', 'K3'] },
{ term: 'bloat', vi: 'Phình bảng', topic: 'db', def: 'Bảng hoặc index chiếm nhiều đĩa hơn dữ liệu thật vì đầy dòng chết chưa được dọn. Làm scan chậm, cache kém hiệu quả; sửa bằng vacuum đúng cấu hình hoặc pg_repack.', see: ['K3'] },
{ term: 'WAL', alt: ['write-ahead log', 'write ahead log'], vi: 'Nhật ký ghi trước', topic: 'db', def: 'Mọi thay đổi được ghi tuần tự vào log trước khi áp vào trang dữ liệu; nhờ vậy commit nhanh (ghi tuần tự) và khôi phục được sau sập. Cũng là nguồn cho replication và CDC.', see: ['F4', 'F5', 'B2'] },
{ term: 'index', alt: ['chỉ mục', 'indexes'], vi: 'Chỉ mục', topic: 'db', def: 'Cấu trúc phụ (thường B-tree) giúp tìm dòng theo cột mà không quét cả bảng. Mỗi index làm ghi chậm hơn và tốn đĩa, nên chỉ tạo cho truy vấn thật sự chạy.', see: ['F5', 'K3'] },
{ term: 'B-tree', alt: ['btree', 'b-tree index'], vi: 'Cây B', topic: 'db', def: 'Cấu trúc cây cân bằng, mọi lá cùng độ sâu, tìm/chèn/xoá O(log n), hỗ trợ so sánh phạm vi và sắp xếp. Là index mặc định của Postgres và hầu hết DB quan hệ.', see: ['F5', 'B4'] },
{ term: 'composite index', alt: ['leftmost prefix', 'multi-column index'], vi: 'Chỉ mục nhiều cột', topic: 'db', def: 'Index trên (a, b, c) dùng được cho truy vấn lọc theo a, theo a và b, theo a, b, c — nhưng không cho truy vấn chỉ lọc theo b (quy tắc tiền tố trái). Thứ tự cột quyết định tất cả.', see: ['F5', 'K3'] },
{ term: 'covering index', alt: ['index-only scan', 'INCLUDE'], vi: 'Chỉ mục bao phủ', topic: 'db', def: 'Index chứa đủ mọi cột truy vấn cần nên DB trả kết quả ngay từ index, không cần đọc bảng (index-only scan). Postgres hỗ trợ thêm cột bằng INCLUDE.', see: ['F5', 'K3'] },
{ term: 'partial index', vi: 'Chỉ mục một phần', topic: 'db', def: 'Index chỉ trên các dòng thoả điều kiện WHERE (ví dụ status = pending). Nhỏ hơn hàng trăm lần, rất hợp cho hàng đợi trong bảng hoặc trạng thái hiếm.', ex: 'Bảng 700k dòng pending: partial index giảm truy vấn từ hàng phút xuống mili giây.', see: ['F5', 'K3'] },
{ term: 'selectivity', vi: 'Độ chọn lọc', topic: 'db', def: 'Tỉ lệ dòng mà một điều kiện lọc ra. Điều kiện chọn lọc cao (ít dòng) thì index có ích; cột chỉ có 2–3 giá trị (status, is_deleted) thì planner thường quét bảng vì rẻ hơn.', see: ['F5'] },
{ term: 'EXPLAIN ANALYZE', alt: ['EXPLAIN', 'query plan', 'execution plan'], vi: 'Kế hoạch thực thi', topic: 'db', def: 'Lệnh Postgres hiển thị cách truy vấn được thực thi (Seq Scan, Index Scan, Nested Loop, Hash Join) kèm số dòng ước lượng và thực tế. Chênh lệch lớn giữa hai số là dấu hiệu thống kê cũ.', see: ['F5', 'K3'] },
{ term: 'sequential scan', alt: ['seq scan', 'full table scan', 'table scan'], vi: 'Quét tuần tự', topic: 'db', def: 'Đọc toàn bộ bảng từ đầu tới cuối. Hợp lý khi bảng nhỏ hoặc lấy phần lớn dòng; là thảm hoạ khi bảng hàng triệu dòng mà chỉ cần vài dòng.', see: ['F5'] },
{ term: 'N+1', alt: ['N+1 query', 'N+1 problem'], vi: 'Vấn đề N+1', topic: 'db', def: 'Lấy danh sách N bản ghi rồi với mỗi bản ghi lại chạy một truy vấn con, tổng N+1 truy vấn. Sửa bằng JOIN, truy vấn IN theo lô hoặc dataloader.', see: ['K3', 'F6'] },
{ term: 'PgBouncer', vi: 'Bộ gom kết nối Postgres', topic: 'db', def: 'Proxy đứng trước Postgres gom hàng nghìn kết nối client vào vài chục kết nối thật. Chế độ transaction pooling mạnh nhất nhưng làm mất tham số phiên (SET) giữa các giao dịch.', see: ['F5', 'K3'] },
{ term: 'statement_timeout', alt: ['lock_timeout', 'idle_in_transaction_session_timeout'], vi: 'Giới hạn thời gian câu lệnh', topic: 'db', def: 'Tham số Postgres huỷ câu lệnh chạy quá lâu. Đặt được ở cấp cluster, role, session hoặc SET LOCAL trong giao dịch; đặt ở cấp role ảnh hưởng mọi truy vấn kể cả job nền dài.', see: ['F5', 'L2', 'K3'] },
{ term: 'lock', alt: ['row lock', 'table lock'], vi: 'Khoá', topic: 'db', def: 'Cơ chế DB ngăn hai giao dịch sửa cùng dữ liệu đồng thời. Khoá dòng là bình thường; khoá bảng khi ALTER hoặc CREATE INDEX không CONCURRENTLY sẽ chặn mọi truy vấn.', see: ['F5', 'B18'] },
{ term: 'deadlock', vi: 'Khoá chết', topic: 'concurrency', def: 'Hai bên cùng giữ khoá mà bên kia cần nên không ai tiến được. Postgres tự phát hiện và huỷ một giao dịch; phòng bằng cách luôn lấy khoá theo cùng thứ tự.', see: ['F5', 'K2', 'K3'] },
{ term: 'advisory lock', vi: 'Khoá tư vấn', topic: 'db', def: 'Khoá do ứng dụng đặt tên và tự quản trong Postgres, không gắn với dòng nào. Cách rẻ để bảo đảm chỉ một instance chạy job định kỳ mà không cần etcd hay ZooKeeper.', see: ['B6', 'L10', 'C18'] },
{ term: 'SELECT FOR UPDATE', alt: ['FOR UPDATE'], vi: 'Khoá dòng khi đọc', topic: 'db', def: 'Đọc dòng và khoá nó tới hết giao dịch để không ai sửa chen ngang; là khoá bi quan. Dùng cho trừ tồn kho, đặt phòng; đi kèm giao dịch thật ngắn.', see: ['F5', 'C16'] },
{ term: 'SKIP LOCKED', vi: 'Bỏ qua dòng đang khoá', topic: 'db', def: 'Tuỳ chọn của SELECT FOR UPDATE để nhiều worker cùng lấy việc từ một bảng mà không chờ nhau: mỗi worker nhận các dòng chưa ai khoá. Biến Postgres thành hàng đợi đủ dùng.', see: ['B6', 'C18', 'L6'] },
{ term: 'optimistic locking', alt: ['optimistic concurrency', 'khoá lạc quan'], vi: 'Khoá lạc quan', topic: 'db', def: 'Không khoá khi đọc; khi ghi kiểm tra cột version chưa đổi (UPDATE ... WHERE version = n). Xung đột thì retry. Hợp khi tranh chấp hiếm.', see: ['F5', 'K2', 'C16'] },
{ term: 'pessimistic locking', alt: ['khoá bi quan'], vi: 'Khoá bi quan', topic: 'db', def: 'Khoá dữ liệu ngay khi đọc để chắc không ai sửa trước khi mình ghi (SELECT FOR UPDATE). An toàn khi tranh chấp cao nhưng giảm thông lượng và dễ deadlock.', see: ['F5', 'C16'] },
{ term: 'keyset pagination', alt: ['cursor pagination', 'cursor-based pagination', 'seek pagination'], vi: 'Phân trang theo con trỏ', topic: 'api', def: 'Lấy trang tiếp bằng điều kiện WHERE (id, created_at) > giá trị cuối trang trước, dùng index nên trang thứ 1 000 vẫn nhanh và không trùng/sót khi dữ liệu đổi.', see: ['F6', 'B10'] },
{ term: 'offset pagination', alt: ['LIMIT OFFSET'], vi: 'Phân trang theo OFFSET', topic: 'api', def: 'LIMIT 20 OFFSET 20000 bắt DB đọc và bỏ 20 000 dòng, càng về sau càng chậm; dữ liệu chèn vào giữa làm trùng dòng. Chỉ dùng cho bảng nhỏ hoặc cần nhảy trang.', see: ['F6'] },
{ term: 'upsert', alt: ['ON CONFLICT'], vi: 'Chèn hoặc cập nhật', topic: 'db', def: 'INSERT ... ON CONFLICT DO UPDATE: chèn nếu chưa có, cập nhật nếu đã có, trong một câu lệnh nguyên tử. Nền của consumer idempotent và bảng dedup.', see: ['K3', 'B7'] },
{ term: 'FDW', alt: ['foreign data wrapper', 'postgres_fdw'], vi: 'Bọc dữ liệu ngoài', topic: 'db', def: 'Cơ chế Postgres truy vấn bảng ở DB khác như bảng cục bộ. Tiện nhưng JOIN qua FDW khó đẩy điều kiện sang bên kia và schema remote bị "đóng băng" lúc IMPORT, đổi cột là lỗi.', see: ['K3', 'B18'] },
{ term: 'partitioning', alt: ['table partitioning', 'declarative partitioning', 'phân vùng bảng'], vi: 'Phân vùng bảng', topic: 'db', def: 'Chia một bảng lớn thành nhiều bảng con theo khoảng (thời gian) hoặc hash (tenant) trong cùng DB. Truy vấn có điều kiện phân vùng chỉ chạm bảng con; xoá dữ liệu cũ bằng DROP partition.', see: ['B3', 'K3'] },
{ term: 'replication', alt: ['nhân bản dữ liệu'], vi: 'Nhân bản dữ liệu', topic: 'consistency', def: 'Giữ nhiều bản sao dữ liệu trên nhiều máy để chịu lỗi và chia tải đọc. Đồng bộ (sync) an toàn nhưng chậm; bất đồng bộ (async) nhanh nhưng có độ trễ và có thể mất dữ liệu khi failover.', see: ['B2'] },
{ term: 'leader-follower', alt: ['leader', 'follower', 'primary', 'primary-replica', 'master-slave', 'single-leader'], vi: 'Chủ - theo', topic: 'consistency', def: 'Mô hình một node nhận mọi ghi (leader/primary) và phát thay đổi cho các node theo (follower/replica). Đơn giản, không xung đột ghi, nhưng leader là điểm nghẽn ghi.', see: ['B2'] },
{ term: 'read replica', alt: ['replica', 'read replicas'], vi: 'Bản sao đọc', topic: 'consistency', def: 'Bản sao chỉ đọc của DB để chia tải truy vấn đọc và báo cáo. Dữ liệu trễ hơn primary vài ms tới vài giây; đọc ngay sau ghi phải về primary.', see: ['B2', 'F10'] },
{ term: 'replication lag', vi: 'Độ trễ nhân bản', topic: 'consistency', def: 'Khoảng thời gian replica đi sau primary. Bình thường mili giây, nhưng tăng vọt khi primary ghi dồn dập hoặc replica chạy truy vấn nặng; là nguồn của lỗi "vừa lưu xong mà không thấy".', see: ['B2'] },
{ term: 'read-your-writes', alt: ['read your writes', 'read-after-write'], vi: 'Đọc được điều mình vừa ghi', topic: 'consistency', def: 'Bảo đảm người dùng luôn thấy thay đổi của chính họ dù đọc từ replica. Thực hiện bằng đọc từ primary trong N giây sau khi ghi hoặc so LSN/phiên bản.', see: ['B2', 'B5'] },
{ term: 'monotonic reads', alt: ['consistent prefix'], vi: 'Đọc không lùi', topic: 'consistency', def: 'Khi đã thấy dữ liệu mới thì không bao giờ thấy phiên bản cũ hơn ở lần đọc sau (tránh "nhảy lùi" khi hai lần đọc rơi vào hai replica khác nhau). Thực hiện bằng gắn người dùng với một replica.', see: ['B2', 'B5'] },
{ term: 'split brain', alt: ['split-brain'], vi: 'Não tách đôi', topic: 'consistency', def: 'Hai node cùng tưởng mình là leader (do mất liên lạc) và cùng nhận ghi, dữ liệu phân nhánh không hợp nhất được. Chặn bằng quorum, fencing token, lease.', see: ['B2', 'B6'] },
{ term: 'fencing token', vi: 'Thẻ rào', topic: 'consistency', def: 'Số tăng dần cấp cùng với lock/lease; tài nguyên từ chối thao tác mang token nhỏ hơn token mới nhất đã thấy. Chặn client giữ lock cũ (bị treo rồi tỉnh lại) ghi đè dữ liệu.', see: ['B6'] },
{ term: 'lease', vi: 'Thuê quyền có hạn', topic: 'consistency', def: 'Quyền (làm leader, giữ lock) chỉ có hiệu lực trong một khoảng thời gian và phải gia hạn bằng heartbeat; hết hạn thì tự mất. Tránh lock bị giữ vĩnh viễn khi người giữ chết.', see: ['B6', 'C18'] },
{ term: 'sharding', alt: ['shard', 'shards', 'database sharding'], vi: 'Phân mảnh', topic: 'scale', def: 'Chia dữ liệu theo khoá sang nhiều DB độc lập để vượt giới hạn ghi và dung lượng của một máy. Trả giá: truy vấn xuyên shard, giao dịch xuyên shard, rebalancing khó. Làm sau cùng, sau index, cache, replica, partition.', see: ['B3'] },
{ term: 'shard key', alt: ['partition key', 'khoá phân mảnh'], vi: 'Khoá phân mảnh', topic: 'scale', def: 'Cột quyết định dữ liệu nằm ở shard nào. Cần phân bố đều, có mặt trong truy vấn chính và ít đổi. Chọn sai (ví dụ theo ngày) sinh hot shard.', see: ['B3', 'B4'] },
{ term: 'consistent hashing', alt: ['consistent hash', 'băm nhất quán'], vi: 'Băm nhất quán', topic: 'scale', def: 'Xếp node và key lên một vòng tròn băm; key thuộc node kế tiếp theo chiều kim đồng hồ. Thêm hoặc bớt một node chỉ di chuyển khoảng 1/N số key thay vì gần như toàn bộ như hash modulo.', see: ['B3', 'C3', 'L5'] },
{ term: 'virtual node', alt: ['vnode', 'virtual nodes'], vi: 'Node ảo', topic: 'scale', def: 'Mỗi node vật lý xuất hiện nhiều điểm trên vòng băm nhất quán (100–200 điểm) để dữ liệu phân bố đều hơn và khi một node rời đi, tải của nó chia cho nhiều node khác.', see: ['B3', 'L5'] },
{ term: 'rebalancing', alt: ['resharding'], vi: 'Cân bằng lại', topic: 'scale', def: 'Di chuyển dữ liệu giữa các shard/partition khi thêm bớt node hoặc khi phân bố lệch. Tốn băng thông và dễ ảnh hưởng truy vấn, nên làm từ từ và có kế hoạch.', see: ['B3', 'B8'] },
{ term: 'secondary index', alt: ['local secondary index', 'global secondary index', 'LSI', 'GSI'], vi: 'Chỉ mục phụ', topic: 'scale', def: 'Index trên cột không phải shard key. Local: mỗi shard tự index phần của mình, truy vấn phải hỏi mọi shard (scatter-gather). Global: index được phân mảnh theo cột index, đọc một shard nhưng ghi phải cập nhật hai nơi.', see: ['B3', 'B4'] },
{ term: 'scatter-gather', alt: ['scatter gather'], vi: 'Rải và gom', topic: 'scale', def: 'Gửi truy vấn tới mọi shard rồi gộp kết quả. Độ trễ bằng shard chậm nhất và tải nhân với số shard; tránh cho đường nóng bằng cách thiết kế shard key theo truy vấn.', see: ['B3', 'B11'] },
{ term: 'denormalization', alt: ['denormalize', 'phi chuẩn hoá'], vi: 'Phi chuẩn hoá', topic: 'storage', def: 'Lưu lặp dữ liệu (tên tác giả trong bảng bài viết) để đọc không cần JOIN. Đọc nhanh, nhưng ghi phải cập nhật nhiều nơi và dễ lệch.', see: ['B4', 'C6'] },

/* --- 4. NoSQL & consistency --- */
{ term: 'key-value store', alt: ['KV store', 'key-value'], vi: 'Kho khoá-giá trị', topic: 'storage', def: 'DB chỉ có GET/PUT/DELETE theo khoá (Redis, DynamoDB, Riak). Scale ngang dễ, độ trễ thấp, nhưng không truy vấn theo giá trị hay JOIN.', see: ['B4', 'C3'] },
{ term: 'wide-column', alt: ['wide column', 'column-family'], vi: 'Cột rộng', topic: 'storage', def: 'Mô hình Cassandra/Bigtable: dữ liệu nhóm theo partition key và sắp theo clustering key, mỗi dòng có thể có cột khác nhau. Ghi rất nhanh (LSM), truy vấn phải thiết kế trước theo access pattern.', see: ['B4', 'C7'] },
{ term: 'document store', alt: ['document database', 'MongoDB'], vi: 'Kho tài liệu', topic: 'storage', def: 'Lưu bản ghi dạng JSON lồng nhau (MongoDB). Linh hoạt schema, đọc cả tài liệu một lần; nhưng quan hệ nhiều-nhiều và giao dịch nhiều tài liệu vụng hơn DB quan hệ.', see: ['B4'] },
{ term: 'graph database', alt: ['graph DB'], vi: 'DB đồ thị', topic: 'storage', def: 'Lưu node và cạnh, truy vấn đi theo quan hệ nhiều bước (bạn của bạn) nhanh hơn JOIN đệ quy. Chỉ đáng dùng khi truy vấn quan hệ sâu là trung tâm.', see: ['B4'] },
{ term: 'LSM-tree', alt: ['LSM tree', 'LSM', 'log-structured merge tree'], vi: 'Cây gộp theo log', topic: 'storage', def: 'Cấu trúc ghi vào bộ nhớ (memtable) rồi đổ xuống đĩa thành file bất biến (SSTable) và gộp dần (compaction). Ghi tuần tự nên rất nhanh; đọc phải tra nhiều file nên cần bloom filter.', see: ['B4', 'C3'] },
{ term: 'SSTable', alt: ['sorted string table'], vi: 'Bảng chuỗi đã sắp', topic: 'storage', def: 'File bất biến chứa cặp khoá-giá trị sắp theo khoá, có index thưa; đơn vị lưu trữ của LSM-tree. Không sửa tại chỗ, chỉ ghi file mới rồi gộp.', see: ['B4'] },
{ term: 'memtable', vi: 'Bảng trong bộ nhớ', topic: 'storage', def: 'Cấu trúc sắp thứ tự trong RAM nhận mọi ghi của LSM-tree; đầy thì đổ xuống đĩa thành SSTable. Được bảo vệ bằng WAL để không mất khi sập.', see: ['B4'] },
{ term: 'compaction', vi: 'Gộp file', topic: 'storage', def: 'Tiến trình nền của LSM gộp nhiều SSTable, loại bản ghi cũ và đã xoá. Giảm read amplification nhưng tốn I/O; cấu hình sai gây đột biến độ trễ.', see: ['B4', 'B8'] },
{ term: 'write amplification', alt: ['read amplification', 'space amplification'], vi: 'Khuếch đại ghi / đọc', topic: 'storage', def: 'Tỉ lệ giữa lượng I/O thật và lượng dữ liệu logic. B-tree khuếch đại ghi (sửa cả trang), LSM khuếch đại đọc (tra nhiều tầng). Chọn engine theo tỉ lệ đọc/ghi.', see: ['B4'] },
{ term: 'bloom filter', vi: 'Bộ lọc Bloom', topic: 'storage', def: 'Cấu trúc xác suất rất nhỏ trả lời "chắc chắn không có" hoặc "có thể có". Dùng để bỏ qua SSTable không chứa khoá, chặn URL đã crawl, chống cache penetration. Khoảng 10 bit mỗi phần tử cho 1% sai dương.', see: ['B4', 'C17', 'L9'] },
{ term: 'strong consistency', alt: ['nhất quán mạnh'], vi: 'Nhất quán mạnh', topic: 'consistency', def: 'Mọi lần đọc sau khi ghi thành công đều thấy giá trị mới, như chỉ có một bản dữ liệu. Trả giá bằng độ trễ (chờ quorum) và kém sẵn sàng khi mạng chia cắt.', see: ['B5'] },
{ term: 'linearizability', alt: ['linearizable'], vi: 'Tuyến tính hoá', topic: 'consistency', def: 'Mức nhất quán mạnh nhất cho từng đối tượng: mọi thao tác như xảy ra tức thời tại một điểm giữa lúc gửi và lúc nhận kết quả, theo thứ tự thời gian thực. Cần cho lock, leader election, số dư.', see: ['B5'] },
{ term: 'eventual consistency', alt: ['eventually consistent', 'nhất quán cuối cùng'], vi: 'Nhất quán cuối cùng', topic: 'consistency', def: 'Các bản sao có thể khác nhau tạm thời nhưng nếu ngừng ghi thì sẽ hội tụ. Cho phép sẵn sàng và nhanh; ứng dụng phải chịu được dữ liệu cũ vài giây.', see: ['B5'] },
{ term: 'causal consistency', vi: 'Nhất quán nhân quả', topic: 'consistency', def: 'Nếu thao tác B xảy ra vì thấy A thì mọi người thấy B cũng phải thấy A trước (câu trả lời không xuất hiện trước câu hỏi). Yếu hơn linearizability, không cần đồng hồ toàn cục.', see: ['B5'] },
{ term: 'CAP theorem', alt: ['CAP'], vi: 'Định lý CAP', topic: 'consistency', def: 'Khi mạng bị chia cắt (P), hệ thống phải chọn giữa nhất quán (C: từ chối phục vụ) hoặc sẵn sàng (A: phục vụ dữ liệu có thể cũ). Không phải "chọn 2 trong 3" lúc bình thường.', see: ['B5'] },
{ term: 'PACELC', vi: 'Mở rộng của CAP', topic: 'consistency', def: 'Khi có Partition thì chọn A hay C; Else (bình thường) chọn Latency hay Consistency. Nhắc rằng ngay cả khi mạng tốt, nhất quán mạnh vẫn trả giá bằng độ trễ.', see: ['B5'] },
{ term: 'quorum', alt: ['W + R > N', 'majority'], vi: 'Túc số', topic: 'consistency', def: 'Ghi cần W bản xác nhận, đọc hỏi R bản; nếu W + R > N thì đọc chắc chắn gặp ít nhất một bản mới nhất. Chỉnh W, R để đổi giữa độ trễ ghi và độ trễ đọc.', see: ['B5', 'C3'] },
{ term: 'hinted handoff', alt: ['sloppy quorum'], vi: 'Giao tạm có ghi chú', topic: 'consistency', def: 'Khi node đích tạm chết, node khác nhận ghi hộ kèm ghi chú và trả lại khi node đích sống. Giữ hệ thống sẵn sàng (sloppy quorum) nhưng làm yếu bảo đảm của quorum.', see: ['B5', 'C3'] },
{ term: 'read repair', alt: ['anti-entropy'], vi: 'Sửa khi đọc / chống entropy', topic: 'consistency', def: 'Read repair: khi đọc thấy bản sao lệch, ghi lại giá trị mới nhất cho bản cũ. Anti-entropy: tiến trình nền so sánh toàn bộ (Merkle tree) để đồng bộ dữ liệu ít được đọc.', see: ['B5', 'C3'] },
{ term: 'Merkle tree', alt: ['hash tree'], vi: 'Cây băm', topic: 'consistency', def: 'Cây mà mỗi node là hash của các con; so sánh gốc rồi đi xuống nhánh khác nhau tìm đúng phần dữ liệu lệch giữa hai bản sao mà không truyền toàn bộ.', see: ['B5'] },
{ term: 'vector clock', alt: ['version vector', 'Lamport timestamp', 'Lamport clock'], vi: 'Đồng hồ vector', topic: 'consistency', def: 'Mỗi node giữ bộ đếm riêng, gắn vào mỗi phiên bản dữ liệu để biết hai phiên bản có quan hệ trước-sau hay xung đột (concurrent). Lamport timestamp đơn giản hơn, chỉ cho thứ tự toàn phần không phát hiện xung đột.', see: ['B5', 'B10', 'C3'] },
{ term: 'last-write-wins', alt: ['LWW', 'last write wins'], vi: 'Ghi sau thắng', topic: 'consistency', def: 'Giải xung đột bằng timestamp lớn nhất. Đơn giản nhưng âm thầm mất dữ liệu và phụ thuộc đồng hồ máy; chỉ dùng khi mất một bản cập nhật là chấp nhận được.', see: ['B5'] },
{ term: 'CRDT', alt: ['conflict-free replicated data type'], vi: 'Kiểu dữ liệu hợp nhất không xung đột', topic: 'consistency', def: 'Cấu trúc (bộ đếm, tập hợp, văn bản) mà mọi bản sao hợp nhất theo luật toán học luôn ra cùng kết quả bất kể thứ tự. Dùng cho soạn thảo cộng tác, đếm like offline.', see: ['B5'] },
{ term: 'consensus', alt: ['đồng thuận'], vi: 'Đồng thuận', topic: 'consistency', def: 'Nhiều node thống nhất một giá trị (ai là leader, thứ tự log) dù có node chết. Raft, Paxos cần đa số (2f+1 node chịu được f lỗi). Chậm và hạn chế quy mô, nên chỉ dùng cho metadata và điều phối.', see: ['B6'] },
{ term: 'Raft', alt: ['Paxos'], vi: 'Thuật toán Raft', topic: 'consistency', def: 'Thuật toán đồng thuận dễ hiểu: bầu leader theo nhiệm kỳ (term), leader nhân bản log tới follower, một mục được commit khi đa số đã ghi. Nền của etcd, Consul, CockroachDB.', see: ['B6'] },
{ term: 'leader election', vi: 'Bầu leader', topic: 'consistency', def: 'Chọn một node duy nhất làm việc gì đó (chạy cron, nhận ghi). Dùng Raft/etcd/ZooKeeper, hoặc đơn giản là advisory lock Postgres kèm lease và heartbeat.', see: ['B6', 'C18', 'L10'] },
{ term: '2PC', alt: ['two-phase commit', 'two phase commit'], vi: 'Commit hai pha', topic: 'consistency', def: 'Coordinator hỏi mọi bên "sẵn sàng chưa" (prepare) rồi ra lệnh commit. Nguyên tử xuyên hệ thống nhưng blocking: coordinator chết giữa chừng thì mọi bên giữ khoá chờ. Hiếm dùng trong microservice.', see: ['B7'] },
{ term: 'saga', alt: ['saga pattern'], vi: 'Chuỗi giao dịch bù', topic: 'queue', def: 'Giao dịch dài chia thành nhiều bước cục bộ; bước nào hỏng thì chạy các bước bù (compensating) cho những bước trước. Choreography: service tự nghe sự kiện; orchestration: một bộ điều phối ra lệnh.', see: ['B7', 'C11'] },
{ term: 'compensating transaction', alt: ['compensation'], vi: 'Giao dịch bù', topic: 'queue', def: 'Thao tác đảo ngược hiệu quả nghiệp vụ của bước đã commit (hoàn tiền, trả tồn kho) vì không thể rollback thật. Phải tự nó idempotent và có thể chạy muộn.', see: ['B7'] },
{ term: 'outbox pattern', alt: ['transactional outbox', 'outbox'], vi: 'Hộp thư đi', topic: 'queue', def: 'Ghi sự kiện vào bảng outbox trong cùng giao dịch với dữ liệu nghiệp vụ; một relay đọc bảng và publish lên broker. Bảo đảm không mất sự kiện và không publish trước khi commit.', see: ['B7', 'L6'] },
{ term: 'inbox pattern', alt: ['dedup table', 'inbox'], vi: 'Hộp thư đến', topic: 'queue', def: 'Consumer lưu message id đã xử lý vào bảng (cùng giao dịch với tác dụng của nó); gặp lại id thì bỏ qua. Biến at-least-once thành effectively-once.', see: ['B7', 'L4'] },
{ term: 'CDC', alt: ['change data capture', 'Debezium'], vi: 'Bắt thay đổi dữ liệu', topic: 'data', def: 'Đọc WAL/binlog của DB để phát mọi INSERT/UPDATE/DELETE thành luồng sự kiện (Debezium → Kafka). Đồng bộ sang search, cache, warehouse mà không sửa code ứng dụng.', see: ['B7', 'B11'] },
{ term: 'event sourcing', vi: 'Lưu theo sự kiện', topic: 'data', def: 'Lưu chuỗi sự kiện bất biến làm nguồn sự thật, trạng thái hiện tại tính bằng cách phát lại (có snapshot). Lịch sử đầy đủ, dễ audit; truy vấn và sửa schema sự kiện khó.', see: ['B8'] },
{ term: 'CQRS', alt: ['command query responsibility segregation'], vi: 'Tách đường ghi và đọc', topic: 'data', def: 'Mô hình ghi (command) và mô hình đọc (query) tách riêng, đọc từ view được cập nhật bất đồng bộ. Tối ưu từng phía nhưng view luôn trễ hơn ghi.', see: ['B8', 'B13'] },
{ term: 'materialized view', alt: ['pre-aggregation', 'precomputed view'], vi: 'View vật chất hoá', topic: 'data', def: 'Kết quả truy vấn được tính trước và lưu như bảng, làm mới định kỳ hoặc theo sự kiện. Đổi dữ liệu tươi lấy tốc độ đọc cho dashboard, báo cáo.', see: ['B13', 'C12'] },
{ term: 'dual write', alt: ['dual-write'], vi: 'Ghi kép', topic: 'queue', def: 'Ghi DB rồi publish broker (hoặc cập nhật cache) bằng hai thao tác riêng; bước hai hỏng hoặc commit hỏng sau khi đã publish là lệch dữ liệu. Thay bằng outbox hoặc CDC.', see: ['B7'] },

/* --- 5. Queue & data --- */
{ term: 'message broker', alt: ['broker'], vi: 'Môi giới thông điệp', topic: 'queue', def: 'Hệ thống trung gian nhận message từ producer và giao cho consumer (RabbitMQ, Kafka, SQS). Tách rời hai bên về thời gian và tốc độ; là nơi cần theo dõi consumer lag.', see: ['F8', 'B8'] },
{ term: 'pub/sub', alt: ['publish/subscribe', 'publish-subscribe'], vi: 'Xuất bản - đăng ký', topic: 'queue', def: 'Producer phát lên topic, mọi subscriber quan tâm đều nhận bản sao. Khác queue điểm-điểm nơi mỗi message chỉ một consumer xử lý.', see: ['F8', 'B20'] },
{ term: 'event-driven', alt: ['event-driven architecture', 'EDA'], vi: 'Hướng sự kiện', topic: 'queue', def: 'Service phản ứng với sự kiện phát ra từ service khác thay vì gọi nhau trực tiếp. Giảm phụ thuộc, dễ thêm consumer; đổi lại khó theo dõi luồng và nhất quán cuối cùng.', see: ['B8', 'B16'] },
{ term: 'Kafka', alt: ['Apache Kafka'], vi: 'Kafka', topic: 'queue', def: 'Log phân tán, bền, phân vùng: message giữ theo retention chứ không xoá khi đã đọc, consumer tự quản offset. Thông lượng rất cao, phát lại được; vận hành nặng hơn RabbitMQ/SQS.', see: ['B8', 'C15'] },
{ term: 'topic', alt: ['topics'], vi: 'Chủ đề', topic: 'queue', def: 'Tên luồng message trong Kafka/SNS; chia thành nhiều partition để song song. Producer ghi vào topic, consumer group đọc từ topic.', see: ['B8'] },
{ term: 'partition', alt: ['partitions', 'Kafka partition'], vi: 'Phân vùng', topic: 'queue', def: 'Đơn vị song song và thứ tự của Kafka: message cùng khoá vào cùng partition và được đọc đúng thứ tự; mỗi partition tại một thời điểm chỉ một consumer trong group đọc.', see: ['B8', 'C15'] },
{ term: 'offset', alt: ['offsets', 'consumer offset'], vi: 'Vị trí đọc', topic: 'queue', def: 'Số thứ tự message trong partition mà consumer đã xử lý tới; commit offset sau khi xử lý để không mất, commit trước thì at-most-once.', see: ['B8', 'C15'] },
{ term: 'consumer group', vi: 'Nhóm consumer', topic: 'queue', def: 'Tập consumer chia nhau các partition của một topic; thêm consumer tới số partition thì tăng song song. Mỗi group có offset riêng nên nhiều group đọc cùng topic độc lập.', see: ['B8'] },
{ term: 'consumer lag', vi: 'Độ trễ tiêu thụ', topic: 'observability', def: 'Khoảng cách giữa message mới nhất và message consumer đã xử lý (hoặc độ sâu queue). Metric số một của hệ bất đồng bộ: tăng đều nghĩa là consumer không theo kịp hoặc đã chết.', see: ['F8', 'B14'] },
{ term: 'retention', alt: ['log compaction', 'compacted topic'], vi: 'Thời gian lưu', topic: 'queue', def: 'Kafka giữ message theo thời gian hoặc dung lượng rồi xoá; log compaction thay vào đó chỉ giữ giá trị mới nhất của mỗi khoá, biến topic thành bảng trạng thái.', see: ['B8'] },
{ term: 'ISR', alt: ['in-sync replicas', 'acks=all'], vi: 'Bản sao đồng bộ', topic: 'queue', def: 'Tập replica của partition Kafka đang theo kịp leader. Producer với acks=all chỉ được xác nhận khi mọi ISR đã ghi, đổi độ trễ lấy độ bền.', see: ['B8', 'C15'] },
{ term: 'RabbitMQ', alt: ['AMQP'], vi: 'RabbitMQ', topic: 'queue', def: 'Broker theo AMQP: producer gửi vào exchange, exchange định tuyến vào queue, consumer ack từng message. Linh hoạt routing, độ trễ thấp; message xoá khi đã ack nên không phát lại được.', see: ['F8', 'B8', 'L4'] },
{ term: 'exchange', alt: ['direct exchange', 'topic exchange', 'fanout exchange'], vi: 'Bộ định tuyến', topic: 'queue', def: 'Thành phần RabbitMQ nhận message và đẩy vào queue theo quy tắc: direct (khớp đúng routing key), topic (khớp mẫu), fanout (gửi mọi queue gắn vào), headers.', see: ['B8'] },
{ term: 'ack', alt: ['nack', 'acknowledgement', 'manual ack'], vi: 'Xác nhận', topic: 'queue', def: 'Consumer báo broker đã xử lý xong (ack) hoặc thất bại (nack, có thể requeue). Ack sau khi xử lý xong và lưu DB; ack sớm là mất message khi sập.', see: ['F8', 'B8'] },
{ term: 'prefetch', alt: ['prefetch count', 'QoS'], vi: 'Lấy trước', topic: 'queue', def: 'Số message broker giao cho một consumer mà chưa cần ack. Nhỏ thì chia đều nhưng chậm; lớn thì nhanh nhưng một consumer chết giữ nhiều message. Là một dạng backpressure.', see: ['F8', 'B8'] },
{ term: 'publisher confirm', alt: ['publisher confirms'], vi: 'Xác nhận phía gửi', topic: 'queue', def: 'Broker báo lại producer rằng message đã được nhận và ghi; không bật thì publish là "gửi rồi quên", broker chết là mất mà không biết. Kèm reconnect để publisher không chết im lặng.', see: ['B8', 'L4'] },
{ term: 'DLQ', alt: ['dead letter queue', 'dead-letter queue', 'DLX', 'dead letter exchange'], vi: 'Hàng đợi thư chết', topic: 'queue', def: 'Nơi chứa message thất bại sau N lần retry để không chặn hàng đợi chính và để điều tra sau. DLX là exchange RabbitMQ chuyển message bị nack/hết hạn sang DLQ.', see: ['F8', 'B8', 'L4'] },
{ term: 'visibility timeout', vi: 'Thời gian ẩn', topic: 'queue', def: 'Trong SQS, message được giao sẽ ẩn với consumer khác trong khoảng này; không xoá kịp thì hiện lại và được giao lần nữa. Đặt dài hơn thời gian xử lý tối đa, hoặc gia hạn khi đang xử lý.', see: ['F8', 'K7'] },
{ term: 'FIFO queue', alt: ['FIFO', 'ordering'], vi: 'Hàng đợi đúng thứ tự', topic: 'queue', def: 'Bảo đảm thứ tự và không trùng (SQS FIFO theo message group, Kafka theo partition). Giá: thông lượng thấp hơn và một message kẹt chặn cả nhóm.', see: ['F8', 'B8'] },
{ term: 'SNS fan-out', alt: ['SNS', 'SQS', 'SNS to SQS'], vi: 'Phát toả bằng SNS', topic: 'cloud', def: 'Publish một lần lên SNS topic, mỗi SQS queue đăng ký nhận một bản để xử lý độc lập. Cách chuẩn trên AWS để một sự kiện kích hoạt nhiều consumer.', see: ['B8', 'K7'] },
{ term: 'poison message', alt: ['poison pill'], vi: 'Thông điệp độc', topic: 'queue', def: 'Message mà consumer luôn thất bại (dữ liệu hỏng, lỗi code) khiến nó bị retry mãi, chặn hàng đợi. Giới hạn số lần rồi đưa sang DLQ; cô lập lỗi theo từng item trong batch.', see: ['F8', 'B17'] },
{ term: 'schema evolution', alt: ['schema registry', 'backward compatible', 'forward compatible'], vi: 'Tiến hoá schema', topic: 'queue', def: 'Thay đổi cấu trúc message mà producer/consumer cũ mới vẫn hiểu nhau: chỉ thêm trường tuỳ chọn, không đổi nghĩa trường cũ. Protobuf/Avro với schema registry kiểm tra tương thích tự động.', see: ['B8'] },
{ term: 'Protobuf', alt: ['Protocol Buffers', 'Avro', 'gRPC'], vi: 'Định dạng nhị phân có schema', topic: 'api', def: 'Protobuf và Avro mã hoá dữ liệu nhị phân nhỏ gọn theo schema, có quy tắc tương thích khi thêm trường. gRPC là RPC trên HTTP/2 dùng Protobuf, hợp cho giao tiếp nội bộ giữa service.', see: ['F6', 'B8'] },
{ term: 'OLTP', vi: 'Xử lý giao dịch trực tuyến', topic: 'data', def: 'Khối lượng công việc nhiều giao dịch nhỏ, đọc/ghi vài dòng theo khoá (đặt hàng, đăng nhập). DB hàng (row store) với index tối ưu cho việc này.', see: ['B13'] },
{ term: 'OLAP', vi: 'Phân tích trực tuyến', topic: 'data', def: 'Truy vấn tổng hợp quét hàng triệu dòng theo vài cột (doanh thu theo tháng). Dùng DB cột (columnar) như ClickHouse, Redshift, BigQuery; tách khỏi OLTP để báo cáo không làm chậm giao dịch.', see: ['B13', 'C13'] },
{ term: 'columnar storage', alt: ['column store', 'Parquet', 'columnar'], vi: 'Lưu trữ theo cột', topic: 'data', def: 'Lưu từng cột liền nhau nên truy vấn chỉ đọc cột cần, nén rất tốt, tổng hợp nhanh gấp nhiều lần row store. Kém cho cập nhật từng dòng.', see: ['B13'] },
{ term: 'data warehouse', alt: ['data lake', 'lakehouse'], vi: 'Kho dữ liệu / hồ dữ liệu', topic: 'data', def: 'Warehouse: dữ liệu đã làm sạch, có schema, phục vụ BI. Lake: lưu thô mọi định dạng trên object storage, schema áp lúc đọc. Lakehouse ghép cả hai với format bảng mở.', see: ['B13'] },
{ term: 'ETL', alt: ['ELT'], vi: 'Trích xuất - biến đổi - nạp', topic: 'data', def: 'Pipeline chuyển dữ liệu từ hệ giao dịch sang kho phân tích. ETL biến đổi trước khi nạp; ELT nạp thô rồi biến đổi trong warehouse nhờ sức mạnh tính toán của nó.', see: ['B13'] },
{ term: 'batch processing', alt: ['batch job', 'batch'], vi: 'Xử lý theo lô', topic: 'data', def: 'Xử lý khối dữ liệu lớn theo lịch (hằng đêm). Đơn giản, dễ chạy lại, nhưng kết quả trễ theo chu kỳ lô.', see: ['B13'] },
{ term: 'stream processing', alt: ['streaming', 'Flink', 'Kafka Streams'], vi: 'Xử lý luồng', topic: 'data', def: 'Xử lý sự kiện liên tục ngay khi tới (Flink, Kafka Streams), kết quả trong giây. Phải xử lý thứ tự lệch, sự kiện đến muộn, trạng thái và exactly-once bằng checkpoint.', see: ['B13', 'C13'] },
{ term: 'window', alt: ['tumbling window', 'sliding window aggregation', 'session window'], vi: 'Cửa sổ thời gian', topic: 'data', def: 'Cách gom sự kiện luồng để tổng hợp: tumbling (khối không chồng, mỗi phút), sliding (chồng nhau), session (theo khoảng nghỉ của người dùng).', see: ['B13', 'C13'] },
{ term: 'watermark', vi: 'Mốc nước', topic: 'data', def: 'Ước lượng "mọi sự kiện có thời gian trước mốc này đã tới" để hệ luồng biết khi nào đóng cửa sổ. Sự kiện đến sau watermark là late data, phải bỏ hoặc sửa kết quả.', see: ['B13', 'C13'] },
{ term: 'late data', alt: ['late event', 'out-of-order'], vi: 'Dữ liệu đến muộn', topic: 'data', def: 'Sự kiện có event time cũ nhưng tới sau khi cửa sổ đã đóng (mạng chậm, thiết bị offline). Chọn chấp nhận sai số, giữ cửa sổ mở thêm, hoặc phát bản sửa.', see: ['B13', 'C13'] },
{ term: 'checkpoint', alt: ['checkpointing'], vi: 'Điểm kiểm tra', topic: 'data', def: 'Ảnh chụp định kỳ trạng thái và offset của job luồng để khôi phục đúng chỗ sau sập mà không trùng kết quả. Cách Flink đạt exactly-once nội bộ.', see: ['B13'] },
{ term: 'MapReduce', alt: ['Spark', 'Hadoop'], vi: 'MapReduce', topic: 'data', def: 'Mô hình chia việc: map biến mỗi bản ghi thành cặp khoá-giá trị, shuffle gom theo khoá, reduce tổng hợp. Spark kế thừa ý tưởng nhưng giữ dữ liệu trong RAM nên nhanh hơn nhiều.', see: ['B13'] },
{ term: 'lambda architecture', alt: ['kappa architecture'], vi: 'Kiến trúc lambda / kappa', topic: 'data', def: 'Lambda: chạy song song tầng batch (chính xác, trễ) và tầng speed (nhanh, xấp xỉ) rồi gộp. Kappa: chỉ dùng luồng, chạy lại bằng cách phát lại log. Kappa đơn giản hơn nếu broker giữ dữ liệu đủ lâu.', see: ['B13', 'C13'] }
];
